/* The circuit, generated by tools/art/track_data.py (do not edit): the surface map (one SURF_* per 8 x 8 px cell of
   the 1024 x 1024 px plane), the centre line (a point every TRACK_POINT_STEP px from the start/finish line, in lap
   order), the AI waypoints (x, y, target speed Q16.16) and the grid (x, y, heading per kart). */
#ifndef TRACK_H
#define TRACK_H
#include <stdint.h>

#define TRACK_CELLS       128
#define TRACK_CELL        8
#define TRACK_POINTS      678
#define TRACK_POINT_STEP  8
#define TRACK_LEN         5424       /* TRACK_POINTS * TRACK_POINT_STEP: arc positions are point index * step */
#define TRACK_SECTORS     32
#define TRACK_WAYPOINTS   34
#define TRACK_PADS        3
#ifndef N_KARTS
#define N_KARTS 4
#endif

extern const uint8_t md_cells[TRACK_CELLS * TRACK_CELLS];
extern const int16_t md_points[TRACK_POINTS][2];
extern const int32_t md_waypoints[TRACK_WAYPOINTS][3];
extern const int16_t md_grid[N_KARTS][3];
extern const int32_t md_track_points;

#endif
